using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct SettlementId : IEquatable<SettlementId>, IComparable<SettlementId>
    {
        public Guid Value { get; }

        public SettlementId(Guid value)
        {
            Value = value;
        }

        public static SettlementId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static SettlementId NewRandom() => new SettlementId(Guid.NewGuid());

        public static SettlementId Parse(string text) => new SettlementId(Guid.Parse(text));

        public static bool TryParse(string text, out SettlementId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new SettlementId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(SettlementId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is SettlementId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(SettlementId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(SettlementId left, SettlementId right) => left.Equals(right);

        public static bool operator !=(SettlementId left, SettlementId right) => !left.Equals(right);
    }
}
